descriptor.controllerScript:
self.onInit = function() {
    var html5QrCode;

    self.onDataUpdated = function() {
        // Wait for DOM to mount before updating the select box
        setTimeout(function() {
            if (self.ctx.data.length > 0) {
                var attrData = self.ctx.data.find(d => d.dataKey.name === 'available_courses');
                var select = $('#courseSelect', self.ctx.$container);
                if (select.length === 0) return;

                var currentSelection = select.val();
                select.empty();

                if (attrData && attrData.data.length > 0) {
                    var val = attrData.data[0][1];
                    var courses = val ? val.split(',').map(c => c.trim()).filter(c => c && c !== 'undefined') : [];
                    courses.forEach(function(course) {
                        select.append(`<option value="${course}">${course}</option>`);
                    });
                    if(courses.length === 0) select.append('<option value="">No courses found</option>');
                    else if (currentSelection && courses.includes(currentSelection)) select.val(currentSelection);
                } else {
                    select.append('<option value="">No courses found</option>');
                }
            }
        }, 500);
    };

    // Wait for DOM to mount before attaching button click
    setTimeout(function() {
        $('#scanBtn', self.ctx.$container).on('click', function() {
            var selectedCourse = $('#courseSelect', self.ctx.$container).val();
            if(!selectedCourse || selectedCourse === 'No courses found') {
                alert('Please wait for courses to load, or ask an admin to add courses.');
                return;
            }

            $(this).hide(); // Hide scan button
            $('#reader', self.ctx.$container).show();
            $('#status', self.ctx.$container).text("Starting camera...").css('color', 'blue');

            try {
                html5QrCode = new Html5Qrcode("reader");
                html5QrCode.start(
                    { facingMode: "environment" }, 
                    { fps: 10, qrbox: { width: 250, height: 250 } },
                    function onScanSuccess(scannedToken, decodedResult) {
                        html5QrCode.stop().then(function() {
                            $('#reader', self.ctx.$container).hide();
                            $('#scanBtn', self.ctx.$container).show();
                            sendAttendance(scannedToken, selectedCourse);
                        });
                    },
                    function onScanFailure(error) { }
                ).catch(function(err) {
                    $('#status', self.ctx.$container).text("Camera access denied.").css('color', 'red');
                    $('#scanBtn', self.ctx.$container).show();
                    $('#reader', self.ctx.$container).hide();
                });
            } catch(e) {
                $('#status', self.ctx.$container).text("Camera library error.");
            }
        });
    }, 500);

    function sendAttendance(token, course) {
        $('#status', self.ctx.$container).text("Sending...").css('color', '#f39c12');

        var telemetry = {
            qr_token: token,
            course: course,
            user_email: self.ctx.currentUser.email
        };

        fetch('https://eu.thingsboard.cloud/api/v1/KQYXoDYomNDMJ29qdH0k/telemetry', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(telemetry)
        }).then(response => {
            if (response.ok || response.type === 'opaque') {
                $('#status', self.ctx.$container).text("✅ Attendance Logged for " + course + "!").css('color', '#27ae60');
            } else {
                throw new Error('Network error');
            }
        }).catch(error => {
            $('#status', self.ctx.$container).text("❌ Network Error.").css('color', 'red');
        });
    }
};
